use std::alloc::{GlobalAlloc,Layout,System};use std::sync::atomic::AtomicUsize;
static LIVE:AtomicUsize=AtomicUsize::new(0);static PEAK:AtomicUsize=AtomicUsize::new(0);
fn add(n:usize){let v=LIVE.fetch_add(n,Ordering::Relaxed)+n;PEAK.fetch_max(v,Ordering::Relaxed);}
struct Tracking;unsafe impl GlobalAlloc for Tracking{unsafe fn alloc(&self,l:Layout)->*mut u8{let p=unsafe{System.alloc(l)};if !p.is_null(){add(l.size());}p}unsafe fn dealloc(&self,p:*mut u8,l:Layout){LIVE.fetch_sub(l.size(),Ordering::Relaxed);unsafe{System.dealloc(p,l)}}unsafe fn realloc(&self,p:*mut u8,l:Layout,n:usize)->*mut u8{let q=unsafe{System.realloc(p,l,n)};if !q.is_null(){LIVE.fetch_sub(l.size(),Ordering::Relaxed);add(n);}q}}#[global_allocator]static ALLOC:Tracking=Tracking;
static ROOT:std::sync::OnceLock<std::path::PathBuf>=std::sync::OnceLock::new();fn project()->&'static Path{ROOT.get().unwrap().as_path()}
// Only new cross-mode resources/identity/large-map cases; shared R480 runtime.
use lito_modern::modern_lito::{native_multisector_resources::{self,Inputs},native_city_runtime::{Runtime,Action,UiPage,UiFrame},native_mode_menu::Filter,native_resources::BytePin};
use std::{path::Path,fs,thread,time::{Duration,Instant},sync::atomic::Ordering};use sha2::{Digest,Sha256};use serde_json::{Value,json};
fn input(name:&str)->Inputs{let p=project();let manifest=p.join(format!("logs/continuation-20261003/{name}"));let b=fs::read(&manifest).unwrap();Inputs{project:p.into(),manifest,manifest_pin:BytePin{bytes:b.len() as u64,sha256:Sha256::digest(b).into()}}}
fn wait(mut f:impl FnMut()->bool){let until=Instant::now()+Duration::from_secs(90);while !f(){assert!(Instant::now()<until,"R484 bounded wait timeout");thread::sleep(Duration::from_millis(5));}}
fn choose(rt:&mut Runtime,mode:u8,id:u32){rt.handle(Action::Filter(Filter::Mode{mode,alternate:false})).unwrap();rt.handle(Action::Select(mode,id)).unwrap();}
fn enter(rt:&mut Runtime,retries:&mut usize){wait(||match rt.handle(Action::Enter){Ok(())=>true,Err(e)=>{assert!(e.to_string().contains("背景工作尚未可接受"),"unexpected Enter refusal: {e}");*retries+=1;false}});}
fn pixels(p:&Path)->Vec<u8>{let mut d=png::Decoder::new(fs::File::open(p).unwrap()).read_info().unwrap();let mut b=vec![0;d.output_buffer_size()];let i=d.next_frame(&mut b).unwrap();assert_eq!(i.color_type,png::ColorType::Rgba);b.truncate(i.buffer_size());b}
fn save(p:&Path,f:&UiFrame)->Value{let rgba:Vec<_>=f.bgra().unwrap().chunks_exact(4).flat_map(|p|[p[2],p[1],p[0],p[3]]).collect();let mut e=png::Encoder::new(fs::File::create(p).unwrap(),800,600);e.set_color(png::ColorType::Rgba);e.set_depth(png::BitDepth::Eight);e.write_header().unwrap().write_image_data(&rgba).unwrap();let b=fs::read(p).unwrap();json!({"path":p,"bytes":b.len(),"sha256":format!("{:X}",Sha256::digest(b)),"rgba_sha256":format!("{:X}",Sha256::digest(rgba))})}
fn fixture(root:&Path,m:&Value,name:&str)->Inputs{let path=root.join(name);let b=serde_json::to_vec_pretty(m).unwrap();fs::write(&path,&b).unwrap();Inputs{project:project().into(),manifest:path,manifest_pin:BytePin{bytes:b.len() as u64,sha256:Sha256::digest(b).into()}}}
fn close(rt:&mut Runtime){rt.handle(Action::Close).unwrap();wait(||{rt.poll();rt.page()==UiPage::Closed});assert!(rt.progress().retired.load(Ordering::Acquire));}
fn failed(i:Inputs,mode:u8,id:u32)->String{let mut rt=Runtime::start(i).unwrap();wait(||{rt.poll();rt.page()==UiPage::Menu});choose(&mut rt,mode,id);let mut retries=0;enter(&mut rt,&mut retries);wait(||{rt.poll();rt.page()==UiPage::Menu});assert_eq!((rt.choice().unwrap().mode,rt.choice().unwrap().map_id),(mode,id));assert!(rt.frame().is_none()&&rt.status().contains("載入失敗"));let s=rt.status().to_owned();close(&mut rt);s}

fn wrapped(block:&[u8])->Vec<u8>{let mut b=1u32.to_le_bytes().to_vec();b.extend(0u32.to_le_bytes());b.extend((block.len()as u32).to_le_bytes());b.extend(block);b}
fn same(a:lito_modern::modern_lito::map::S32Sector,b:lito_modern::modern_lito::map::S32Sector){assert_eq!((a.floor,a.overlays,a.attributes,a.objects,a.opacity,a.tile_dependencies,a.portals,a.effects,a.effects_extended,a.layer_ranges,a.unknown_trailing),(b.floor,b.overlays,b.attributes,b.objects,b.opacity,b.tile_dependencies,b.portals,b.effects,b.effects_extended,b.layer_ranges,b.unknown_trailing));}
fn base_map()->Vec<u8>{let mut b=vec![0;32768];b.extend(0u16.to_le_bytes());b.extend(vec![0;16384]);b.extend(0i32.to_le_bytes());b.extend(0i32.to_le_bytes());b.extend(0i32.to_le_bytes());b}
fn portal(b:&mut Vec<u8>,name:&[u8],kind:Option<u8>){b.push(name.len()as u8);b.extend(name);b.extend([4,5]);b.extend(573u16.to_le_bytes());b.extend(0x0018ffe6i32.to_le_bytes());if let Some(k)=kind{b.push(k);}}
